"""Generated by AutoAir from the visual DAG spec 'blueprints'.

Do not edit by hand: changes are overwritten on the next deploy.
Edit the DAG in the AutoAir builder (spec: blueprints.autoair.json) instead."""

import datetime

from airflow.providers.standard.operators.empty import EmptyOperator
from airflow.sdk import DAG, TaskGroup

from tests.blueprint_templates.etl import (
    Extract,
    ExtractConfig,
    ExtractV2,
    Load,
    LoadConfig,
    NotifyConfig,
    TeamNotifier,
)

with DAG(
    dag_id="blueprints",
    description="Astronomer Blueprint steps next to regular tasks",
    schedule="@daily",
    start_date=datetime.datetime(2024, 1, 1),
    catchup=False,
) as dag:
    g_ingest = TaskGroup(group_id="ingest")
    t_start = EmptyOperator(task_id="start")
    extract_customers_blueprint = Extract()
    extract_customers_blueprint.step_id = "extract_customers"
    with g_ingest:
        g_extract_customers = extract_customers_blueprint.render(
            ExtractConfig(source_table="raw.customers", batch_size=500)
        )
    extract_orders_blueprint = ExtractV2()
    extract_orders_blueprint.step_id = "extract_orders"
    with g_ingest:
        g_extract_orders = extract_orders_blueprint.render(
            ExtractV2.get_config_type()(tables=["orders", "order_lines"])
        )
    load_blueprint = Load()
    load_blueprint.step_id = "load"
    g_load = load_blueprint.render(
        LoadConfig(target_table="analytics.customer_orders", mode="overwrite")
    )
    notify_blueprint = TeamNotifier()
    notify_blueprint.step_id = "notify"
    g_notify = notify_blueprint.render(NotifyConfig())
    t_start >> g_ingest
    g_ingest >> g_load
    g_load >> g_notify
